<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StudentProfileController extends Controller{
 private function access(Request $r,$student,$write=false){$u=$r->user();$ok=$u->student_id==$student||$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')||$u->canDo('students.manage');abort_unless($ok,403);if($write&&$u->student_id==$student&&!($u->isSuperAdmin()||$u->canDo('students.manage')))abort(403);}
 public function edit(Request $r,$student){$this->access($r,$student);$s=DB::table('students')->find($student);abort_if(!$s,404);return view('student.private',['s'=>$s,'profile'=>DB::table('student_private_profiles')->where('student_id',$student)->first(),'representatives'=>DB::table('student_representatives')->where('student_id',$student)->get(),'achievements'=>DB::table('student_achievements')->where('student_id',$student)->orderByDesc('achievement_date')->get()]);}
 public function update(Request $r,$student){$this->access($r,$student,true);$d=$r->validate(['birth_date'=>'nullable|date','phone'=>'nullable|string|max:80','email'=>'nullable|email|max:180','address'=>'nullable|string|max:1000','education_document'=>'nullable|string|max:255','snils'=>'nullable|string|max:50','medical_policy'=>'nullable|string|max:100','dormitory'=>'nullable|string|max:255','benefit_category'=>'nullable|string|max:255','scholarship'=>'nullable|string|max:255','military_status'=>'nullable|string|max:255','has_medical_restrictions'=>'nullable|boolean','medical_restrictions_note'=>'nullable|string|max:3000']);$d['has_medical_restrictions']=$r->boolean('has_medical_restrictions');DB::table('student_private_profiles')->updateOrInsert(['student_id'=>$student],array_merge($d,['created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Закрытая часть личного дела сохранена.');}
 public function representative(Request $r,$student){$this->access($r,$student,true);$d=$r->validate(['relation'=>'required|string|max:100','full_name'=>'required|string|max:255','phone'=>'nullable|string|max:80','email'=>'nullable|email|max:180','address'=>'nullable|string|max:1000']);DB::table('student_representatives')->insert(array_merge($d,['student_id'=>$student,'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Представитель добавлен.');}
 public function achievement(Request $r,$student){$this->access($r,$student,true);$d=$r->validate(['achievement_date'=>'nullable|date','type'=>'required|string|max:100','title'=>'required|string|max:255','level'=>'nullable|string|max:100','description'=>'nullable|string|max:3000']);DB::table('student_achievements')->insert(array_merge($d,['student_id'=>$student,'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Достижение добавлено.');}
}